`timescale 1ns/1ps
module tb_spi_master;
    reg clk;
    reg rst_n;
    reg start;
    reg [7:0] tx_data;
    wire miso;
    wire [7:0] rx_data;
    wire busy;
    wire done;
    wire sclk;
    wire cs_n;
    wire mosi;

    assign miso = ~mosi;

    spi_master dut (
        .clk(clk),
        .rst_n(rst_n),
        .start(start),
        .tx_data(tx_data),
        .miso(miso),
        .rx_data(rx_data),
        .busy(busy),
        .done(done),
        .sclk(sclk),
        .cs_n(cs_n),
        .mosi(mosi)
    );

    always #5 clk = ~clk;

    initial begin
        #10000;
        $display("FAIL: Simulation watchdog timeout (SPI master transfer hang)");
        $fatal(1);
    end

    initial begin
        clk = 0;
        rst_n = 0;
        start = 0;
        tx_data = 0;
        #20;
        rst_n = 1;
        #10;

        if (busy || cs_n !== 1 || sclk !== 0) begin
            $display("FAIL: SPI Master not idle on reset: busy=%b cs_n=%b sclk=%b", busy, cs_n, sclk);
            $fatal(1);
        end

        @(posedge clk);
        start = 1;
        tx_data = 8'hA5;
        @(posedge clk);
        start = 0;

        while (!done) @(posedge clk);
        #1;
        if (rx_data !== 8'h5A) begin
            $display("FAIL: rx_data mismatch: got %h, expected %h", rx_data, 8'h5A);
            $fatal(1);
        end
        if (cs_n !== 1) begin
            $display("FAIL: cs_n did not return high after transfer");
            $fatal(1);
        end

        $display("ALL_TESTS_PASSED");
        $finish;
    end
endmodule
